import{_ as t,o as i,c as o,a3 as a}from"./chunks/framework.DAK02U1-.js";const p=JSON.parse(`{"title":"Build from Source","description":"clice builds with Bazel alone. Bazel downloads everything the build uses: the C++ toolchain and the prebuilt LLVM/Clang libraries of one xclang release, clice-io's clang toolchain, and the other…","frontmatter":{"head":[["meta",{"property":"og:title","content":"Build from Source | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/clice/guide/build"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/clice/guide/build"}],["meta",{"name":"twitter:card","content":"summary"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/guide/build"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/guide/build"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/guide/build"}],["meta",{"property":"og:description","content":"clice builds with Bazel alone. Bazel downloads everything the build uses: the C++ toolchain and the prebuilt LLVM/Clang libraries of one xclang release, clice-io's clang toolchain, and the other…"}]]},"headers":[],"relativePath":"clice/guide/build.md","filePath":"en/clice/guide/build.md","lastUpdated":1794738697000}`),l={name:"clice/guide/build.md"};function r(c,e,n,d,s,h){return i(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="build-from-source" tabindex="-1">Build from Source <a class="header-anchor" href="#build-from-source" aria-label="Permalink to &quot;Build from Source&quot;">​</a></h1><p>clice builds with <a href="https://bazel.build" target="_blank" rel="noreferrer">Bazel</a> alone. Bazel downloads everything the build uses: the C++ toolchain and the prebuilt LLVM/Clang libraries of one <a href="https://github.com/clice-io/xclang" target="_blank" rel="noreferrer">xclang</a> release, clice-io&#39;s clang toolchain, and the other libraries clice links. The repository&#39;s pixi and npm set up the tools the tests and the docs need; building clice needs neither.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li><p>Bazel, run through <a href="https://github.com/bazelbuild/bazelisk" target="_blank" rel="noreferrer">bazelisk</a>, which fetches the release <code>.bazelversion</code> names.</p></li><li><p>git and <a href="https://nodejs.org" target="_blank" rel="noreferrer">Node.js</a> on <code>PATH</code>: the build stamps clice with the version <code>git describe</code> gives, through a Node script.</p></li><li><p>On Windows, Bash (which <a href="https://gitforwindows.org" target="_blank" rel="noreferrer">Git for Windows</a> includes) and a short Bazel output root, as Bazel&#39;s default one is too deep for Windows paths. Put it in <code>%USERPROFILE%\\.bazelrc</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>startup --output_user_root=C:/b</span></span></code></pre></div></li></ul><h2 id="building" tabindex="-1">Building <a class="header-anchor" href="#building" aria-label="Permalink to &quot;Building&quot;">​</a></h2><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bazel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> //:bin/clice</span></span></code></pre></div><p>clice is <code>build/RelWithDebInfo/bin/bin/clice</code>, beside the resource directory it reads clang&#39;s headers from, <code>build/RelWithDebInfo/bin/lib/clang</code>.</p><p>The build types are configurations, each with a directory of its own, <code>build/&lt;type&gt;</code>:</p><table tabindex="0"><thead><tr><th>Configuration</th><th>Effect</th></tr></thead><tbody><tr><td><code>--config=RelWithDebInfo</code></td><td>The default: optimized, with debug info</td></tr><tr><td><code>--config=Debug</code></td><td>Light optimization (<code>-O1</code>) with Address Sanitizer, on x86_64 Linux and arm64 macOS</td></tr></tbody></table><p><code>--platforms=@xclang//platforms:&lt;triple&gt;</code> builds for another target: x86_64 Linux builds every other one, for example <code>--platforms=@xclang//platforms:aarch64-apple-darwin</code>.</p><p>The LLVM/Clang libraries hold ThinLTO bitcode, so every link of a program redoes their code generation, minutes per program. lld keeps what it generated in a cache, <code>/var/tmp/xclang-thinlto</code> (<code>C:/xclang-thinlto</code> on Windows), and later links take seconds.</p><p><code>bazel build //:package //:symbols</code> builds the release archive and the symbol package, whose <code>clice.gsym</code> <code>scripts/symbolize.py</code> reads: <code>clice.tar.gz</code> and <code>clice-symbol.tar.xz</code> in <code>build/&lt;type&gt;/bin</code> (<code>.zip</code> on Windows).</p><h2 id="working-on-clice" tabindex="-1">Working on clice <a class="header-anchor" href="#working-on-clice" aria-label="Permalink to &quot;Working on clice&quot;">​</a></h2><p><code>bazel run @compdb//:refresh -- --output_groups=+compilation_prerequisites_INTERNAL_</code> writes a <code>compile_commands.json</code> of clice&#39;s own sources to the repository root, for clice to work on its own code; the output group builds the generated headers the commands read.</p><p>The tests need the tools pixi installs. <code>bazel build //:dist</code> builds clice with the unit tests, then <code>pixi run test</code> runs the unit tests and the cases (<code>--config=Debug</code> and <code>pixi run test Debug</code> for the Debug build); <a href="https://github.com/clice-io/clice/blob/main/tests/README.md" target="_blank" rel="noreferrer"><code>tests/README.md</code></a> says how a case is written.</p><h2 id="another-llvm-build" tabindex="-1">Another LLVM Build <a class="header-anchor" href="#another-llvm-build" aria-label="Permalink to &quot;Another LLVM Build&quot;">​</a></h2><p>clice links the LLVM/Clang libraries of the exact version it is written for, not the system&#39;s. A build of one&#39;s own replaces the release&#39;s with <code>--repo_env=XCLANG_LIBCLANG_ROOT=&lt;directory&gt;</code> (<code>XCLANG_LIBCLANG_ASAN_ROOT</code> for the ASan one); it has to be built the way xclang builds it, by xclang&#39;s <code>scripts/toolchain.ts</code>.</p>',17)])])}const b=t(l,[["render",r]]);export{p as __pageData,b as default};
